mapper.select:
 /*setSysopOrderChangeBeforeCheckSave*/
		SELECT
		  COUNT(XX.BUYER_ITEM_NO) AS CNT
		FROM (
            SELECT
             A.BUYER_ITEM_NO
            FROM ICOMIVDT A
                WHERE BUYER =  #{BUYER}
                  AND PO_NO =  #{PO_NO}
                  AND PO_SEQ = #{PO_SEQ}
                  AND STATUS <> 'D'
			UNION ALL
            SELECT
             A.BUYER_ITEM_NO
            FROM ICOMGRDT A
                WHERE BUYER = #{BUYER}
                  AND PO_NO =  #{PO_NO}
                  AND PO_SEQ =  #{PO_SEQ}
                  AND STATUS <> 'D'
   		) XX

/*setSysopOrderChangeBeforeSave1*/

           SELECT                     
           COUNT(*)CNT
           FROM ICOMPORS              
               WHERE BUYER = #{BUYER} 
                 AND PO_NO = #{PO_NO} 
                 AND PO_SEQ = #{PO_SEQ} 
                 AND STATUS <> 'D'

mapper.update:
/*setSysopOrderChangeBeforeSave2*/

UPDATE ICOMPRDT
   SET STATUS        = 'R',
       PO_QTY = #{value},
       RECV_QTY = #{value},
       TARGET_PRICE  = #{value},
       LIST_PRICE    = #{value},
   RD_DATE = #{value},                              
       CHANGE_DATE   = TO_CHAR(SYSDATE, 'YYYYMMDD'),
       CHANGE_TIME   = TO_CHAR(SYSDATE, 'HH24MISS'),
       SELLER_ITEM_NO= #{value},
       REF_PR_NO = #{value},
   MAKER_NAME = #{value},
   MAKER_CODE = #{value},

   DESCRIPTION = #{value},
   SPECIFICATION = #{value},
   UNIT_MEASURE = #{value},
   CMS_CATLG_ID = #{value},
   CMS_CATEG_ID = #{value},
if(docType.equals("X")){
   TARGET_QTY = #{value}
}else{
   TARGET_QTY = TARGET_QTY
}

 WHERE BUYER   = #{value}
   AND PR_NO   = #{value}
   AND PR_SEQ  = #{value}

/*setSysopOrderChangeBeforeSave3*/
UPDATE ICOMPODT SET STATUS= 'R', RD_DATE= #{value} , ITEM_QTY= #{value}, UNIT_PRICE= #{value}, AGENT_PRICE= #{value}, ITEM_AMT= TRUNC( #{value} * #{value} ,2), AGENT_ITEM_AMT= TRUNC( #{value} * #{value} ,2), SEND_DATE= ' ', SEND_TIME= ' ', CHANGE_DATE = TO_CHAR(SYSDATE, 'YYYYMMDD'), CHANGE_TIME = TO_CHAR(SYSDATE, 'HH24MISS'), SELLER_ITEM_NO= #{value}, REF_PR_NO = #{value}, MAKER_NAME = #{value}, MAKER_CODE = #{value},
DESCRIPTION = #{value}, SPECIFICATION = #{value}, UNIT_MEASURE = #{value},
CMS_CATLG_ID = #{value}, CMS_CATEG_ID = #{value}, ORIGIN_CODE = #{value}, KEP_PRICE = NVL(#{value},0), IMPORT_FLAG = NVL(#{value},'N')
WHERE BUYER = #{value} AND PO_NO = #{value} AND PO_SEQ = #{value}

/*setSysopOrderChangeBeforeSave4*/

UPDATE ICOMPOIF_DOOSAN         
   SET RD_DATE        = #{RD_DATE}
 WHERE LEGACY_PO_NO   = #{PO_NO}
   AND LEGACY_PO_SEQ  = #{PO_SEQ}

/*setSysopOrderChangeBeforeProcessTypeModify1*/
UPDATE ICOMPRDT SET AGENT = #{value} , PROCESS_TYPE = #{value}, CHANGE_DATE = TO_CHAR(SYSDATE,'YYYYMMDD'), CHANGE_TIME = TO_CHAR(SYSDATE,'HH24MISS')
WHERE BUYER = #{value} AND PR_NO = #{value} AND PR_SEQ = #{value}

/*setSysopOrderChangeBeforeProcessTypeModify6*/
UPDATE ICOMPOHD PH SET STATUS = DECODE((SELECT NVL(COUNT(*),0) FROM ICOMPODT WHERE BUYER = PH.BUYER AND PO_NO = PH.PO_NO AND STATUS != 'D'), 0, 'D','R'), PO_TTL_AMT = (SELECT NVL(SUM(PD.ITEM_AMT),0) FROM ICOMPODT PD WHERE PH.BUYER = PD.BUYER AND PH.PO_NO = PD.PO_NO AND PD.STATUS != 'D'), PO_TAX_TTL_AMT = (SELECT NVL(SUM(PD.ITEM_AMT),0) FROM ICOMPODT PD WHERE PH.BUYER = PD.BUYER AND PH.PO_NO = PD.PO_NO AND PD.STATUS != 'D'), AGENT_PO_TTL_AMT = (SELECT NVL(SUM(PD.AGENT_ITEM_AMT),0) FROM ICOMPODT PD WHERE PH.BUYER = PD.BUYER AND PH.PO_NO = PD.PO_NO AND PD.STATUS != 'D'), CHANGE_USER_ID = #{st_po_change_user_id}, SEND_DATE = ' ', SEND_TIME = ' ', CHANGE_DATE = TO_CHAR(SYSDATE, 'YYYYMMDD'), CHANGE_TIME = TO_CHAR(SYSDATE, 'HH24MISS')
WHERE BUYER = #{BUYER} AND PO_NO = #{PO_NO}

/*setSysopOrderChangeBeforeAgentModify1*/
UPDATE ICOMPRDT SET AGENT = #{value} , CHANGE_DATE = TO_CHAR(SYSDATE,'YYYYMMDD'), CHANGE_TIME = TO_CHAR(SYSDATE,'HH24MISS'),
LIST_PRICE=#{value}, CMS_CATLG_ID=#{value}, CMS_CATEG_ID=#{value}, MAKER_CODE=#{value}, MAKER_NAME=#{value}
WHERE BUYER = #{value} AND PR_NO = #{value} AND PR_SEQ = #{value}

/*setSysopOrderChangeBeforeInterBizCheck2*/

UPDATE TBL_ORDER_DETAIL SET
   ORDER_DETAIL_STATUS   = '024007'
   ,BS_CUSTOMER_PO_NO   = DECODE(NVL(BS_CUSTOMER_PO_NO,''),'','',BS_CUSTOMER_PO_NO||'_D')
   ,RECORD_MODIFY_DATE       = SYSDATE
   ,RECORD_MODIFY_ID         = #{value}
   ,RECORD_STATUS            = 'M'
WHERE ORDER_DETAIL_CODE = #{value}
  AND RECORD_STATUS ^= 'D'

mapper.select:
 /*setSysopOrderChangeBeforeInterBizCheck3*/

SELECT MIN(ORDER_DETAIL_STATUS)AS V_ORDER_DETAIL_STATUS 
FROM TBL_ORDER_DETAIL 
WHERE ORDER_CODE=#{value}
  AND RECORD_STATUS ^='D'

mapper.update:
/*setSysopOrderChangeBeforeInterBizCheck4*/

UPDATE TBL_ORDER SET
ORDER_STATUS=DECODE(#{value}, '024001', '023001', '024003', '023003', '024004', '023005', '024005', '023004', '024007', '023006', '023001')
WHERE ORDER_CODE= #{value}

/*setSysopOrderChangeBeforeInterBizCheck5*/

UPDATE TBL_ORDER_DETAIL SET
   ORDER_QTY = #{value}
   ,SALE_PRICE=SALE_UNIT_PRICE*#{value}
   ,RECORD_MODIFY_DATE       = SYSDATE
   ,RECORD_MODIFY_ID         = #{value}
   ,RECORD_STATUS            = 'M'
WHERE ORDER_DETAIL_CODE =#{value}
  AND RECORD_STATUS ^= 'D'

mapper.select:
 /*getBuyerRateInfo*/

        SELECT NVL(TOT_RATE,0) FROM TBL_BUYER_PRIMECOST_MNG
WHERE BUYER=#{value}
AND STATUS='C'

 /*getBuyerRateAdaptFlag*/


        SELECT NVL(PRIMECOST_ADAPT,'N') FROM TBL_BUYER_PRIMECOST_MNG
WHERE BUYER=#{value}
AND STATUS='C'

SELECT X.BUYER_NAME AS COM_NAME, MAX(X.AGENT_NAME) COM_NAME2, DECODE(X.AGENT_CODE,'KR00000002',0,SUM(X.PO_AMT)) 발주금액, SUM(X.GR_AMT) 입고금액, DECODE(X.AGENT_CODE,'KR00000002',0,SUM(X.PO_AMT) - SUM(X.GR_AMT)) 미입고금액, DECODE(X.AGENT_CODE,'KR00000002',0,NVL(SUM(X.AGENT_PO_PRICE_AMT),0)) AGENT발주금액, NVL(SUM(X.AGENT_GR_PRICE_AMT),0) AGENT입고금액, X.AGENT_CODE
SELECT MAX(X.AGENT_NAME) AS COM_NAME, X.BUYER_NAME COM_NAME2, DECODE(X.AGENT_CODE,'KR00000002',0,SUM(X.PO_AMT)) 발주금액, SUM(X.GR_AMT) 입고금액, DECODE(X.AGENT_CODE,'KR00000002',0,SUM(X.PO_AMT) - SUM(X.GR_AMT)) 미입고금액, DECODE(X.AGENT_CODE,'KR00000002',0,NVL(SUM(X.AGENT_PO_PRICE_AMT),0)) AGENT발주금액, NVL(SUM(X.AGENT_GR_PRICE_AMT),0) AGENT입고금액, X.AGENT_CODE
FROM (SELECT PO.BUYER, PO.PO_NO, PO.PO_SEQ, MAX((SELECT COM.COM_NAME_LOC FROM ICOMCMPY COM WHERE COM.COM_CODE = PO.BUYER )) AS BUYER_NAME, MAX(DECODE(NVL(GR.AGENT,PH.AGENT),'KR00000002', (SELECT COM_NAME_LOC FROM ICOMCMPY WHERE COM_CODE = PH.AGENT)||'-재고', (SELECT COM_NAME_LOC FROM ICOMCMPY WHERE COM_CODE = PH.AGENT))) AS AGENT_NAME, MAX(NVL(PO.ITEM_AMT,0)) PO_AMT, SUM(NVL(GR.ITEM_AMT,0)) GR_AMT, MAX(NVL(PO.AGENT_ITEM_AMT,0)) AGENT_PO_PRICE_AMT, SUM(NVL(GR.AGENT_ITEM_AMT,0)) AGENT_GR_PRICE_AMT, MAX(NVL(GR.AGENT,PH.AGENT)) AGENT_CODE FROM ICOMPODT PO, ICOMGRDT GR, ICOMPOHD PH, ICOMPRDT R WHERE PO.BUYER = PH.BUYER
AND PO.BUYER = #{st_buyer_code} AND PH.BUYER = #{st_buyer_code}
AND PO.PO_NO = PH.PO_NO AND PO.BUYER = GR.BUYER(+) AND PO.PO_NO = GR.PO_NO(+) AND PO.PO_SEQ = GR.PO_SEQ(+) AND PO.BUYER = R.BUYER AND PO.PR_NO = R.PR_NO AND PO.PR_SEQ = R.PR_SEQ AND PH.STATUS <> 'D' AND PO.STATUS <> 'D' AND R.STATUS <> 'D' AND 'D' <> GR.STATUS(+)
AND GR.BUYER IN (#{st_buyer_code})
AND GR.GR_DATE
AND PH.PO_CREATE_DATE
AND PO.RD_DATE
BETWEEN REPLACE(#{st_from_date},'/','') AND REPLACE(#{st_to_date},'/','') AND R.STATUS <> 'D'
AND PH.AGENT = #{st_agent_code}
AND PH.AGENT = GR.AGENT
AND PO.BUYER_ITEM_NO = #{st_buyer_item_no}
AND R.PURCHASER_DEPT = #{st_po_dept_code}
AND R.REQ_DEPT = #{st_req_dept_code}
AND PO.PO_NO = #{st_po_no}
AND PO.REF_PR_NO = #{st_ref_no}
AND PO.LEGACY_PO_NO = #{st_if_po_no}
AND F_GET_PO_STTS(PO.BUYER, PO.PO_NO , PO.PO_SEQ , 0) IN
#{st_status}
GROUP BY PO.BUYER, PO.PO_NO, PO.PO_SEQ ) X
GROUP BY X.BUYER_NAME,X.AGENT_CODE
GROUP BY X.AGENT_CODE,X.BUYER_NAME
ORDER BY 1,2

SELECT Y.BUYER_NAME 구매사, SUM(Y.PO_SUM_AMT) 발주금액, SUM(Y.GR_SUM_AMT) 입고금액, SUM(Y.RE_GR_SUM_AMT) 미입고금액, SUM(Y.AGENT_PO_SUM_AMT) 매입금액_발주, SUM(Y.AGENT_GR_SUM_AMT) 매입금액_입고 FROM ( SELECT X.BUYER_NAME BUYER_NAME, DECODE(X.AGENT_CODE,'KR00000002',0,SUM(X.PO_AMT)) PO_SUM_AMT, SUM(X.GR_AMT) GR_SUM_AMT, DECODE(X.AGENT_CODE,'KR00000002',0,SUM(X.PO_AMT) - SUM(X.GR_AMT)) RE_GR_SUM_AMT, DECODE(X.AGENT_CODE,'KR00000002',0,NVL(SUM(X.AGENT_PO_PRICE_AMT),0)) AGENT_PO_SUM_AMT, NVL(SUM(X.AGENT_GR_PRICE_AMT),0) AGENT_GR_SUM_AMT, X.AGENT_CODE FROM ( SELECT PO.BUYER, PO.PO_NO, PO.PO_SEQ, MAX((SELECT COM.COM_NAME_LOC FROM ICOMCMPY COM WHERE COM.COM_CODE = PO.BUYER )) AS BUYER_NAME, MAX(NVL(PO.ITEM_AMT,0)) PO_AMT, SUM(NVL(GR.ITEM_AMT,0)) GR_AMT, MAX(PO.AGENT_ITEM_AMT) AGENT_PO_PRICE_AMT, SUM(NVL(GR.AGENT_ITEM_AMT,0)) AGENT_GR_PRICE_AMT, NVL(GR.AGENT,PH.AGENT) AGENT_CODE FROM ICOMPODT PO, ICOMGRDT GR, ICOMPOHD PH, ICOMPRDT R WHERE PO.BUYER = PH.BUYER
AND PO.BUYER IN
#{item}
AND PH.BUYER IN
#{item}
AND PO.PO_NO = PH.PO_NO AND PO.BUYER = GR.BUYER(+) AND PO.PO_NO = GR.PO_NO(+) AND PO.PO_SEQ = GR.PO_SEQ(+) AND PO.BUYER = R.BUYER AND PO.PR_NO = R.PR_NO AND PO.PR_SEQ = R.PR_SEQ AND PH.STATUS <> 'D' AND PO.STATUS <> 'D' AND R.STATUS <> 'D' AND 'D' <> GR.STATUS(+)
AND GR.BUYER IN
#{item}
AND GR.GR_DATE
AND PH.PO_CREATE_DATE
AND PO.RD_DATE
BETWEEN REPLACE(#{st_from_date},'/','') AND REPLACE(#{st_to_date},'/','') AND R.STATUS <> 'D'
AND PO.BUYER_ITEM_NO = #{st_buyer_item_no}
AND R.PURCHASER_DEPT = #{st_po_dept_code}
AND R.REQ_DEPT = #{st_req_dept_code}
AND PO.PO_NO = #{st_po_no}
AND PO.REF_PR_NO = #{st_ref_no}
AND PO.LEGACY_PO_NO = #{st_if_po_no}
AND F_GET_PO_STTS(PO.BUYER, PO.PO_NO , PO.PO_SEQ , 0) IN
#{st_status}
GROUP BY PO.BUYER, PO.PO_NO, PO.PO_SEQ, NVL(GR.AGENT,PH.AGENT) ) X
GROUP BY X.BUYER_NAME,X.AGENT_CODE) Y GROUP BY Y.BUYER_NAME

 /*getBuyerRateAdaptFlag2*/

SELECT NVL((SELECT NVL(PRIMECOST_ADAPT,'N')
FROM TBL_BUYER_PRIMECOST_MNG
WHERE BUYER= #{st_buyer_code}
AND STATUS='C'), 'N')
FROM DUAL
